47	/** Reads a repository's Entire checkpoints into normalized sessions for the given window. */
48	export async function ingest(opts: {
49	  repoUrl: string;
50	  dataDir: string;
51	  since: string;
52	  until: string;
53	  maxSessions?: number;
54	}): Promise<IngestArtifact> {
55	  const repoDir = await cloneOrUpdate(opts.repoUrl, opts.dataDir);
56	  const refs = await listCheckpointRefs(repoDir);
57	  if (refs.length === 0) throw new NoCheckpointsError(`no checkpoint refs found in ${opts.repoUrl}`);
58	
59	  const commitMap = await mapCheckpointCommits(repoDir);
60	  const skipped: { ref: string; reason: string }[] = [];
61	  let allSessions: Session[] = [];
62	  let redactions = 0;
63	
64	  for (const ref of refs) {
65	    try {
66	      const commits = commitMap.get(ref.id) ?? [];
67	      const built = await buildSessionsForCheckpoint(repoDir, ref, commits);
68	      allSessions = allSessions.concat(built.sessions);
69	      redactions += built.redactions;
70	    } catch (err) {
71	      skipped.push({ ref: ref.treeish, reason: err instanceof Error ? err.message : String(err) });
72	    }
73	  }
74	
75	  const merged = mergeSessions(allSessions);
76	  const windowed = selectWindow(merged, opts.since, opts.until, opts.maxSessions ?? DEFAULT_MAX_SESSIONS);
77	
78	  const commitShas = Array.from(new Set(windowed.flatMap((s) => s.commits)));
79	  const diffs: Record<string, string> = {};
80	  for (const sha of commitShas) {
81	    const fileDiffs = await getDiff(repoDir, sha);
82	    for (const [path, patch] of Object.entries(fileDiffs)) diffs[`${sha}:${path}`] = patch;
83	  }
84	
85	  const headSha = await git(repoDir, ['rev-parse', 'HEAD']).then((s) => s.trim()).catch(() => '');
86	
87	  return {
88	    repo: { url: opts.repoUrl, dir: repoDir, headSha },
89	    sessions: windowed,
90	    diffs,
91	    skipped,
92	    enrichments: {},
93	    redactions,
94	  };
95	}
