1	import type { Session } from '@dailies/core';
2	import { classifyCommand, type CommandClass } from './commands';
3	
4	export type RunOutcome = 'pass' | 'fail' | 'unknown';
5	
6	export interface ToolRun {
7	  callEntryId: string;
8	  resultEntryId: string | null;
9	  index: number;
10	  command: string;
11	  cls: CommandClass;
12	  outcome: RunOutcome;
13	}
14	
15	const ANSI = /\x1b\[[0-9;]*[a-zA-Z]/g;
16	
17	function stripAnsi(text: string): string {
18	  return text.replace(ANSI, '');
19	}
20	
21	function parseTestOutcome(text: string): RunOutcome {
22	  for (const m of text.matchAll(/(\d+)\s+(?:failed|failing)/g)) {
23	    if (Number(m[1]) > 0) return 'fail';
24	  }
25	  if (/Tests?:\s+\d+\s+failed/.test(text)) return 'fail';
26	  if (/^FAIL\b/m.test(text)) return 'fail';
27	  if (/AssertionError/.test(text)) return 'fail';
28	
29	  if (/\d+\s+passed/.test(text)) return 'pass';
30	  if (/^PASS\b/m.test(text)) return 'pass';
31	  if (/^ok\s+\S/m.test(text)) return 'pass';
32	  if (/test result: ok/.test(text)) return 'pass';
33	
34	  return 'unknown';
35	}
36	
37	function parseTypecheckOutcome(text: string): RunOutcome {
38	  if (/error TS\d+/.test(text)) return 'fail';
39	  if (/Found [1-9]\d*\s+errors?/.test(text)) return 'fail';
40	  if (/Found 0 errors/.test(text)) return 'pass';
41	  if (text.trim() === '') return 'pass';
42	  return 'unknown';
43	}
44	
45	function parseLintOrBuildOutcome(text: string): RunOutcome {
46	  if (/[1-9]\d*\s+errors?/.test(text)) return 'fail';
47	  if (/[1-9]\d*\s+problems?/.test(text)) return 'fail';
48	  if (text.trim() === '') return 'pass';
49	  if (/compiled successfully/.test(text)) return 'pass';
50	  if (/built in/.test(text)) return 'pass';
51	  if (/Done in/.test(text)) return 'pass';
52	  if (/0 errors/.test(text)) return 'pass';
53	  if (/0 problems/.test(text)) return 'pass';
54	  return 'unknown';
55	}
56	
57	export function parseOutcome(cls: CommandClass, output: string, isError: boolean): RunOutcome {
58	  if (isError) return 'fail';
59	  const text = stripAnsi(output);
60	  if (cls === 'test') return parseTestOutcome(text);
61	  if (cls === 'typecheck') return parseTypecheckOutcome(text);
62	  return parseLintOrBuildOutcome(text);
63	}
64	
65	export function collectRuns(session: Session): ToolRun[] {
66	  const runs: ToolRun[] = [];
67	  for (const call of session.entries) {
68	    if (call.kind !== 'tool_call' || !call.command || call.toolUseId === undefined) continue;
69	    const cls = classifyCommand(call.command);
70	    if (cls === 'other') continue;
71	    const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
72	    const outcome: RunOutcome = result ? parseOutcome(cls, result.text, result.isError ?? false) : 'unknown';
73	    runs.push({
74	      callEntryId: call.id,
75	      resultEntryId: result?.id ?? null,
76	      index: call.index,
77	      command: call.command,
78	      cls,
79	      outcome,
80	    });
81	  }
82	  return runs;
83	}
