4	export function mergeSessions(sessions: Session[]): Session[] {
5	  const byId = new Map<string, Session>();
6	
7	  for (const session of sessions) {
8	    const existing = byId.get(session.id);
9	    if (!existing) {
10	      byId.set(session.id, session);
11	      continue;
12	    }
13	    const longer = session.entries.length > existing.entries.length ? session : existing;
14	    byId.set(session.id, {
15	      ...longer,
16	      checkpointIds: Array.from(new Set([...existing.checkpointIds, ...session.checkpointIds])),
17	      commits: Array.from(new Set([...existing.commits, ...session.commits])),
18	    });
19	  }
20	
21	  return Array.from(byId.values());
22	}
