24	/** Keeps sessions inside [since, until], sorted newest-first, truncated to maxSessions, then returned chronologically. */
25	export function selectWindow(sessions: Session[], since: string, until: string, maxSessions: number): Session[] {
26	  const sinceMs = Date.parse(since);
27	  const untilMs = Date.parse(until);
28	
29	  const inWindow = sessions.filter((s) => {
30	    const startedMs = Date.parse(s.startedAt);
31	    const endedMs = Date.parse(s.endedAt ?? s.startedAt);
32	    return startedMs <= untilMs && endedMs >= sinceMs;
33	  });
34	
35	  const newestFirst = [...inWindow].sort(
36	    (a, b) => Date.parse(b.endedAt ?? b.startedAt) - Date.parse(a.endedAt ?? a.startedAt),
37	  );
38	
39	  return newestFirst.slice(0, maxSessions).sort((a, b) => Date.parse(a.startedAt) - Date.parse(b.startedAt));
