import type { Entry, Session } from '@dailies/core';

export type PartialEntry = {
  kind: Entry['kind'];
  text?: string;
  ts?: string | null;
  toolName?: string;
  toolUseId?: string;
  command?: string;
  filePath?: string;
  isError?: boolean;
};

export function session(entries: PartialEntry[], opts: { id?: string } = {}): Session {
  const id = opts.id ?? 's1';
  const fullEntries: Entry[] = entries.map((e, index) => ({
    id: `${id}:${index}`,
    sessionId: id,
    index,
    ts: e.ts ?? null,
    kind: e.kind,
    text: e.text ?? '',
    toolName: e.toolName,
    toolUseId: e.toolUseId,
    command: e.command,
    filePath: e.filePath,
    isError: e.isError,
  }));
  return {
    id,
    checkpointIds: ['cp1'],
    agent: 'claude-code',
    model: 'claude-sonnet-4.6',
    branch: 'main',
    startedAt: '2026-10-10T07:00:00Z',
    endedAt: '2026-10-10T07:30:00Z',
    turnCount: fullEntries.length,
    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    commits: [],
    filesTouched: [],
    entries: fullEntries,
  };
}

import { describe, expect, it } from 'vitest';
import { collectRuns } from '@dailies/verify';
import { syntheticClaim } from '../src/synthetic';
import { session } from './helpers';

describe('syntheticClaim', () => {
  it('anchors to the next assistant entry and skips runs followed by a source edit', () => {
    const longText = 'A'.repeat(100);
    const sess = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm test' },
      { kind: 'tool_result', toolUseId: 't1', text: 'Tests  14 passed (14)', isError: false },
      { kind: 'assistant', text: longText },
    ]);
    const run = collectRuns(sess)[0]!;
    const c = syntheticClaim(sess, run);
    expect(c).not.toBeNull();
    expect(c!.kind).toBe('tests_pass');
    expect(c!.sessionId).toBe('s1');
    expect(c!.entryId).toBe(sess.entries[2]!.id);
    expect(c!.quote).toBe('A'.repeat(80));
    expect(c!.quote.length).toBe(80);

    const buildSess = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm run build' },
      { kind: 'tool_result', toolUseId: 't1', text: 'built in 1.2s', isError: false },
      { kind: 'assistant', text: 'The build passes.' },
    ]);
    const buildRun = collectRuns(buildSess)[0]!;
    expect(syntheticClaim(buildSess, buildRun)!.kind).toBe('build_passes');

    const editedBetween = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm test' },
      { kind: 'tool_result', toolUseId: 't1', text: 'Tests  14 passed (14)', isError: false },
      { kind: 'tool_call', toolName: 'Edit', toolUseId: 't2', filePath: 'src/retry.ts' },
      { kind: 'assistant', text: 'All tests pass.' },
    ]);
    const editedRun = collectRuns(editedBetween)[0]!;
    expect(syntheticClaim(editedBetween, editedRun)).toBeNull();

    const mdEditBetween = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm test' },
      { kind: 'tool_result', toolUseId: 't1', text: 'Tests  14 passed (14)', isError: false },
      { kind: 'tool_call', toolName: 'Edit', toolUseId: 't2', filePath: 'README.md' },
      { kind: 'assistant', text: 'All tests pass.' },
    ]);
    const mdEditRun = collectRuns(mdEditBetween)[0]!;
    expect(syntheticClaim(mdEditBetween, mdEditRun)).not.toBeNull();

    const noAssistant = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm test' },
      { kind: 'tool_result', toolUseId: 't1', text: 'Tests  14 passed (14)', isError: false },
    ]);
    const noAssistantRun = collectRuns(noAssistant)[0]!;
    expect(syntheticClaim(noAssistant, noAssistantRun)).toBeNull();
  });
});

import type { Claim, Session } from '@dailies/core';
import type { ToolRun } from '@dailies/verify';

const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit']);

function entryIndex(session: Session, entryId: string | null): number | null {
  if (entryId === null) return null;
  return session.entries.find((e) => e.id === entryId)?.index ?? null;
}

/** Builds a tests_pass/build_passes claim anchored to the first assistant entry after the run's
 * result, or null when there is none or a non-markdown source edit sits between them. */
export function syntheticClaim(session: Session, run: ToolRun): Claim | null {
  const afterIndex = entryIndex(session, run.resultEntryId) ?? run.index;
  const assistant = session.entries.find((e) => e.kind === 'assistant' && e.index > afterIndex);
  if (!assistant) return null;

  const edit = session.entries.find(
    (e) =>
      e.kind === 'tool_call' &&
      e.index > afterIndex &&
      e.index < assistant.index &&
      e.toolName !== undefined &&
      EDIT_TOOLS.has(e.toolName) &&
      e.filePath !== undefined &&
      !e.filePath.endsWith('.md'),
  );
  if (edit) return null;

  return {
    id: `synthetic:${run.callEntryId}`,
    sessionId: session.id,
    entryId: assistant.id,
    quote: assistant.text.slice(0, 80),
    kind: run.cls === 'test' ? 'tests_pass' : 'build_passes',
    evidence: [],
  };
}

function canonicalOpposite(run: ToolRun, to: 'pass' | 'fail'): { text: string; isError: boolean } {
  if (run.cls === 'test') {
    return to === 'fail'
      ? { text: 'Tests  3 failed | 11 passed', isError: true }
      : { text: 'Tests  14 passed (14)', isError: false };
  }
  if (run.cls === 'typecheck') {
    return to === 'fail' ? { text: 'error TS2322: mutated', isError: true } : { text: '', isError: false };
  }
  // build/lint share parseLintOrBuildOutcome, whose fail marker is a leading count, not "error TSxxxx".
  return to === 'fail' ? { text: '3 errors', isError: true } : { text: '', isError: false };
}

/** Returns a copy of `session` with the targeted run's recorded result replaced by a canonical
 * opposite outcome; the original session and its other runs are untouched. */
export function mutateRun(session: Session, run: ToolRun, to: 'pass' | 'fail'): Session {
  const copy = structuredClone(session);
  const result = copy.entries.find((e) => e.id === run.resultEntryId);
  if (!result) return copy;
  const { text, isError } = canonicalOpposite(run, to);
  result.text = text;
  result.isError = isError;
  return copy;
}

import { describe, expect, it } from 'vitest';
import { collectRuns, verifyClaim } from '@dailies/verify';
import { mutateRun, syntheticClaim } from '../src/synthetic';
import { runMutationBenchmark } from '../src/mutation';
import { session } from './helpers';

describe('mutateRun', () => {
  it('flips only the targeted run and leaves the original session untouched', () => {
    const sess = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm run build' },
      { kind: 'tool_result', toolUseId: 't1', text: 'built in 1.2s', isError: false },
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't2', command: 'pnpm test' },
      { kind: 'tool_result', toolUseId: 't2', text: 'Tests  14 passed (14)', isError: false },
      { kind: 'assistant', text: 'Build and tests both pass.' },
    ]);
    const runs = collectRuns(sess);
    const buildRun = runs.find((r) => r.cls === 'build')!;
    const testRun = runs.find((r) => r.cls === 'test')!;

    const mutated = mutateRun(sess, testRun, 'fail');

    const mutatedTestResult = mutated.entries.find((e) => e.id === testRun.resultEntryId)!;
    expect(mutatedTestResult.text).toBe('Tests  3 failed | 11 passed');
    expect(mutatedTestResult.isError).toBe(true);

    const mutatedBuildResult = mutated.entries.find((e) => e.id === buildRun.resultEntryId)!;
    expect(mutatedBuildResult.text).toBe('built in 1.2s');
    expect(mutatedBuildResult.isError).toBe(false);

    const originalTestResult = sess.entries.find((e) => e.id === testRun.resultEntryId)!;
    expect(originalTestResult.text).toBe('Tests  14 passed (14)');
    expect(originalTestResult.isError).toBe(false);
  });
});

describe('mutation property', () => {
  it('a passing run mutated to failing goes verified -> contradicted; a failing one goes contradicted -> verified', () => {
    const passing = session([
      { kind: 'tool_call', toolName: 'Bash', toolUseId: 't1', command: 'pnpm test' },
      { kind: 'tool_result', toolUseId: 't1', text: 'Tests  14 passed (14)', isError: false },
      { kind: 'assistant', text: 'All tests pass after the fix.' },
    ]);
    const passRun = collectRuns(passing)[0]!;
    const passClaim = syntheticClaim(passing, passRun)!;
    expect(verifyClaim(passClaim, passing).verdict).toBe('verified');
    const flippedToFail = mutateRun(passing, passRun, 'fail');
    expect(verifyClaim(passClaim, flippedToFail).verdict).toBe('contradicted');

